ui.css:
.panel { background: repeating-linear-gradient(17deg, rgba(120,96,60,.05) 0 1px, transparent 1px 7px), repeating-linear-gradient(-63deg, rgba(255,255,255,.24) 0 1px, transparent 1px 11px), #f4ead4; border: 2.5px solid #1e1b19; box-shadow: inset 0 0 0 3px #f4ead4, inset 0 0 0 4.5px #1e1b19, 0 8px 16px rgba(30,27,25,.3); color: #1e1b19; }
.bar { height: 24px; background: #f4ead4; border: 2px solid #1e1b19; box-shadow: 0 0 0 3px #f4ead4, 0 0 0 4.5px #1e1b19; }
.bar > .fill { height: 100%; background: linear-gradient(180deg, #8e2a1a 0%, #cf4a2c 45%, #e8906a 100%); box-shadow: inset -2px 0 0 rgba(30,27,25,.55); }
.number { font: 400 40px/1 'Zen Antique', serif; color: #1e1b19; text-shadow: 2px 1.5px 0 rgba(36,82,126,.42); }
.slip { writing-mode: vertical-rl; font: 400 12px 'Yuji Syuku', serif; color: #f7eedb; background: #c8402a; padding: 6px 4px; }
.seal { width: 30px; height: 30px; background: #c8402a; border-radius: 2px 4px 2px 5px; box-shadow: inset 0 0 0 2px #c8402a, inset 0 0 0 3.2px rgba(247,238,219,.9); color: #f7eedb; font: 400 16px/30px 'Zen Antique', serif; text-align: center; transform: rotate(-5deg); }
.card { background: linear-gradient(180deg, rgba(23,58,94,.96) 0, rgba(36,82,126,.72) 22px, rgba(126,166,196,0) 92px), #f4ead4; border: 3px solid #1e1b19; box-shadow: inset 0 0 0 5px #f4ead4, inset 0 0 0 6.5px #1e1b19, 0 14px 26px rgba(30,27,25,.38); animation: rise .45s cubic-bezier(.2,.9,.3,1) backwards; }
@keyframes rise { from { transform: translateY(40px); opacity: 0; } to { transform: none; opacity: 1; } }
